    concept: "Emily Brontë 的 Wuthering Heights《咆哮山莊》由 Mr. Earnshaw 收養 Heathcliff 開始。Heathcliff 與 Catherine Earnshaw 一同長大並彼此深愛，但 Hindley 不公平地對待 Heathcliff；Catherine 最後選擇嫁給 Edgar Linton，並在女兒出生後不久去世。悲痛與執念使 Heathcliff 展開復仇：他娶 Isabella 並傷害她，也操控 Edgar 與 Catherine 的女兒 young Cathy、自己的兒子 Linton 及 Hareton，讓下一代承受家族怨恨。後來 young Cathy 與 Hareton 的關係逐漸改善，兩人開始打破仇恨循環。作品探討激情、復仇、執念、怨恨、世代衝突及其後果，也呈現寬恕、和解與救贖的可能；它並非單純的善惡故事。",

