    concept: "William Shakespeare 的 Hamlet《哈姆雷特》描寫丹麥王子 Hamlet 的父王去世後，叔父 Claudius 娶了母親 Gertrude。父王的幽靈聲稱 Claudius 謀殺了他，要求 Hamlet 查明真相並復仇；Hamlet 因良知、疑慮與行動的後果而猶豫，並假裝瘋狂調查真相。他安排戲中戲觀察 Claudius 的反應，之後在母親房中誤殺 Polonius，使他與 Ophelia 的關係更加破裂。Ophelia 在父親死亡及其他打擊後精神崩潰並溺水身亡，劇中未完全說明她的死亡是否出於自殺。Laertes 為父親與妹妹復仇，與 Claudius 合謀安排毒劍及毒酒；決鬥中 Gertrude 飲下毒酒，Hamlet 與 Laertes 被毒劍所傷，Hamlet 殺死 Claudius，並在臨終前將真相託付 Horatio。主要人物相繼死亡，Fortinbras 隨後抵達並接掌丹麥局勢。作品探討復仇、背叛、良知、欺騙、道德兩難、腐敗及行為的後果。",

