// ================================
// 智慧圖庫搜尋
// ================================

function normalizeKeyword(keyword) {

    keyword = keyword.trim();
    keyword = keyword.replace(/\s+/g, "");
    keyword = keyword.toLowerCase();

    return keyword;

}

function calculateScore(item, keyword) {

    let score = 0;

    if (item.title.includes(keyword)) {

    score += 10;

    }

    if (item.concept.includes(keyword)) {

    score += 8;

    }

    if (item.keywords.some(word => word.includes(keyword))) {

    score += 5;

    }

    return score;

}

function filterResults(scoredResults, minScore, limit) {

    const finalResults = [];

    scoredResults.forEach(result => {

        if (result.score >= minScore) {

            finalResults.push({
                ...result.item,
                score: result.score
            });

        }

    });

    return finalResults.slice(0, limit);

}

function sortResults(scoredResults) {

    scoredResults.sort((a, b) => b.score - a.score);

    return scoredResults;

}

function searchImage(keyword) {

    const limit = 3;
    const minScore = 5;

    keyword = normalizeKeyword(keyword);

    if (!keyword) {

        return [];

    }

    const results = [];
    let scoredResults = [];

    diagramMap.forEach(item => {

        const matched =
            item.title.includes(keyword) ||
            item.concept.includes(keyword) ||
            item.keywords.some(
                word => word.includes(keyword)
            );

        if (matched) {

            const score = calculateScore(item, keyword);

            scoredResults.push({
                item: item,
                score: score
            });

        }

    });

    scoredResults = sortResults(scoredResults);


    return filterResults(
        scoredResults,
        minScore,
        limit
    );

}


// 讓 Node.js 工具可以讀取智慧圖庫資料

if (typeof module !== "undefined") {

    module.exports = diagramMap;

}

function getDiagramInfo(question) {

    const text = question.toLowerCase();

    const results = [];

    for (const item of diagramMap) {

    let score = 0;

    for (const keyword of item.keywords) {

        const normalizedKeyword = keyword.toLowerCase();

        const isSingleEnglishWord = /^[a-z]+$/.test(normalizedKeyword);

        const isMatch = normalizedKeyword === "電子"
            ? text === normalizedKeyword
            : isSingleEnglishWord
                ? new RegExp(`\\b${normalizedKeyword}\\b`).test(text)
                : text.includes(normalizedKeyword);

        if (isMatch) {
            score++;

            // 完整命中較長的主題詞，給予額外權重
            if (normalizedKeyword.length >= 2) {
                score += normalizedKeyword.length;
            }
        }

    }

        if (score > 0) {

            results.push({
                item: item,
                score: score
            });

        }
    }

    results.sort((a, b) => b.score - a.score);


    return results
        .slice(0, 3)
        .map(result => result.item);
}
